// 10 个 seed 人物 ID 列表（必须包含）
export const SEED_PEOPLE_IDS = [
  'person-seed-01',
  'person-seed-02',
  'person-seed-03',
  'person-seed-04',
  'person-seed-05',
  'person-seed-06',
  'person-seed-07',
  'person-seed-08',
  'person-seed-09',
  'person-seed-10',
];

// 验证函数
export function validatePeopleStoryMirrors(): {
  total: number;
  seedCount: number;
  allPublicReady: boolean;
  cultureRegionCount: number;
  fieldCount: number;
} {
  const seedIds = new Set(SEED_PEOPLE_IDS);
  const seedCount = peopleStoryMirrors.filter(p => seedIds.has(p.id)).length;
  const allPublicReady = peopleStoryMirrors.every(p => p.review_status === 'public_ready');
  const cultures = new Set(peopleStoryMirrors.map(p => p.culture_region));
  const fields = new Set(peopleStoryMirrors.map(p => p.field));
  return {
    total: peopleStoryMirrors.length,
    seedCount,
    allPublicReady,
    cultureRegionCount: cultures.size,
    fieldCount: fields.size,
  };
}